/* The homepage starts with joining a community and competing. World exploration is optional. */
const traderUI={query:''};
function traderGuilds(){return [...worldGuilds(),...state.drafts.filter(g=>!communityById(g.id))]}
function traderStatus(g){if(g.isNew&&!state.seasonEntries[g.id])return 'TEAM ENTRY NOT CONFIRMED';return state.seasonEntries[g.id]?'LOCAL DEMO ENTRY SAVED':'SAMPLE SEASON ENTRANT'}
function traderEventFacts(){return `<div class="trader-event-facts"><div><small>FORMAT</small><strong>Multi-guild leaderboard</strong></div><div><small>SCHEDULE</small><strong>To be announced</strong></div><div><small>REWARDS</small><strong>Details to follow</strong></div></div>`}
function traderHero(){const g=state.membership&&guildById(state.membership.id);return `<section class="trader-hero"><div class="trader-hero-glow"></div><img class="trader-hero-tower" src="assets/world-arena.webp" alt="" fetchpriority="high"><div class="trader-hero-copy"><span class="page-eyebrow">XOX GUILDS · COMMUNITY DRIVEN TRADING</span><h1>${g?'YOUR GUILD.<br><span>YOUR NEXT CHALLENGE.</span>':'TRADE WITH YOUR PEOPLE.<br><span>COMPETE AS A GUILD.</span>'}</h1><p>${g?`Welcome back, ${escapeHtml(state.membership.name||'Trader')}. Follow your team, know your contribution and get ready for the next round.`:'Join your community’s guild. Trade together.<br>Compete for a place on the leaderboard.'}</p><div class="trader-hero-actions">${g?link('my-guild','Enter my guild '+arrow(),'primary button'):'<a href="#find-community" class="primary button" data-find-community>Find my community '+arrow()+'</a>'}${link('competition','View competition '+arrow(),'text-button')}</div><div class="trader-hero-proof"><span>${icon('users')} One community · One guild</span><span>${icon('trophy')} Season rankings & team battles</span></div></div><aside class="trader-hero-event"><div><span class="trader-event-mark">01</span><span class="demo-chip">EVENT PREVIEW</span></div><small>THE COMMUNITY TRADING COMPETITION</small><h2>GUILD OPEN</h2><p>A shared leaderboard for every community.</p>${traderEventFacts()}${link('competition/rules','Format & eligibility '+arrow(),'text-button')}</aside></section>`}
function traderGuildCard(g){const c=communityById(g.id),own=state.membership?.id===g.id;return `<article class="trader-guild-card ${own?'is-mine':''}"><div class="trader-guild-identity"><img src="${emblem(g)}" alt=""><div><small>${escapeHtml(c?.community||'Community guild')}</small><h3>${escapeHtml(g.name)}</h3></div>${own?'<span class="trader-own-label">MY GUILD</span>':''}</div><p>${escapeHtml(c?.tag||g.description||'Your community. Your shared competition journey.')}</p><div class="trader-guild-meta"><span>${icon('users')} ${g.members.toLocaleString()} members</span><span>${g.policy==='approval'?'Approval required':'Open to join'}</span></div><div class="trader-entry-state"><i></i>${traderStatus(g)}</div><div class="trader-guild-actions">${own?link('my-guild','Open my guild '+arrow(),'primary button'):`<button class="primary" data-join="${g.id}">${g.policy==='approval'?'Apply to join':'Join guild'} ${arrow()}</button>`}${link('guild/'+g.id,'View guild '+arrow(),'text-button')}</div></article>`}
function traderFilteredGuilds(){const term=traderUI.query.trim().toLocaleLowerCase();return traderGuilds().filter(g=>`${g.name} ${communityById(g.id)?.community||''} ${communityById(g.id)?.city||''} ${g.description||''}`.toLocaleLowerCase().includes(term))}
function traderSearchCards(){const gs=traderFilteredGuilds();return gs.length?gs.map(traderGuildCard).join(''):`<div class="trader-search-empty">${icon('search')}<h3>No matching community found.</h3><p>Try a community or guild name, or use your community’s invite link.</p><button class="secondary" data-reset-guild-search>Show all guilds</button><button class="text-button" data-open-guild-invite>Use invite link ${arrow()}</button></div>`}
function traderCommunityFinder(standalone=false){return `<section class="trader-community-finder" id="find-community"><div class="trader-section-heading"><div><span class="page-eyebrow">${standalone?'YOUR COMMUNITY COMES FIRST':'START WITH YOUR COMMUNITY'}</span><h2>Find your people.<br><span>Join their guild.</span></h2><p>Look for a community you know, or meet a new team before joining.</p></div><button class="text-button" data-open-guild-invite>Have an invite link? ${arrow()}</button></div><div class="trader-search-row"><label class="search">${icon('search')}<input id="trader-guild-search" type="search" value="${escapeHtml(traderUI.query)}" placeholder="Search community or guild — Pudgy, Azuki…" aria-label="Search community or guild"></label><span id="trader-guild-count" aria-live="polite">${traderFilteredGuilds().length} guilds</span></div><div class="trader-guild-grid" id="trader-guild-results">${traderSearchCards()}</div><div class="trader-join-note">${icon('shield')} One active guild · No member limit · Joining never activates copying</div></section>`}
function traderGettingStarted(){return `<div class="trader-start-steps">${[['01','Find your community','Choose the team you want to trade with.'],['02','Join the guild','Understand the competition and team entry.'],['03','Trade & track your contribution','Follow your guild’s position and your activity.']].map(([n,t,d])=>`<div><span>${n}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div>`}
function traderMemberBoard(){const g=state.membership&&guildById(state.membership.id);if(!g)return '';const r=typeof journeyRecord==='function'?journeyRecord(g):null,stage=r?.stage||'prepare',personal=r?.trades.reduce((n,t)=>n+t.notional,0)||0,op=stage==='prepare'?null:worldGuilds().find(x=>x.id!==g.id),cta=typeof journeyCTA==='function'?journeyCTA():['arena','Read battle briefing'];return `<section class="trader-member-board"><div class="trader-member-heading"><div><img src="${emblem(g)}" alt=""><span><small>YOUR COMMUNITY · ${escapeHtml(state.membership.role==='owner'?'GUILD LEADER':'GUILD MEMBER')}</small><h2>${escapeHtml(g.name)}</h2></span></div><span class="demo-chip">LOCAL DEMO WORKSPACE</span></div><div class="trader-member-metrics"><div><small>SEASON POSITION · SAMPLE</small><strong>${communityById(g.id)?'#'+guildRank(g):'—'}</strong><span>${communityById(g.id)?'Multi-guild leaderboard':'Team entry required'}</span></div><div><small>GUILD BATTLE</small><strong>${escapeHtml(op?.name||'Prepare with your team')}</strong><span>${op?'Sample opponent · '+stageTitle(stage):'No sample opponent assigned yet'}</span></div><div><small>YOUR ROUND CONTRIBUTION</small><strong>${compactMoney(personal)}</strong><span>${r?.trades.length||0} simulated activity records</span></div><div><small>YOUR NEXT STEP</small><strong>${r?.stage==='final'?'Review your round result':r?.stage==='review'?'Wait for result verification':r?.briefed?'Continue the round':'Read the match briefing'}</strong><span>${r?.stage==='final'?'Review your result and save the round':traderStatus(g)}</span></div></div><div class="trader-member-actions"><button class="primary" data-flow-trade>Go to trade ${arrow()}</button>${link(cta[0],cta[1]+' '+arrow(),'secondary button')}<button class="text-button" data-open-chat="${g.id}">${icon('users')} Team chat</button>${link('my-guild/copy','Optional leader copying '+arrow(),'text-button')}</div></section>`}
function traderStandings(){return `<section class="trader-home-standings"><div class="trader-section-heading"><div><span class="page-eyebrow">THE GUILD OPEN · SEASON PREVIEW</span><h2>Trade as a team.<br><span>Climb together.</span></h2></div>${link('rankings','Full leaderboard '+arrow(),'text-button')}</div><div class="workspace-panel season-standings-panel"><div class="season-panel-top"><div><strong>Guild standings</strong><span class="demo-chip">SAMPLE DATA</span></div>${metricTabs()}</div>${primaryRankTable()}<div class="table-foot"><span>Compare team volume, per-member volume and participation.</span><span>Final scoring to be confirmed</span></div></div></section>`}
function traderLeaderStrip(){return `<section class="trader-home-leaders"><div class="trader-section-heading"><div><span class="page-eyebrow">UNDERSTAND THE PEOPLE LEADING THE TEAMS</span><h2>Public leader performance.</h2><p>Explore their results. Same-guild members can choose to copy separately.</p></div>${link('leaders','View all leaders '+arrow(),'text-button')}</div><div class="trader-leader-list">${captains.map(c=>`<a href="#/leaders/${c.id}"><img src="${emblem(guildById(c.guild))}" alt=""><span><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(guildById(c.guild).name)}</small></span><span><small>30D RETURN · SAMPLE</small><strong class="trader-return">+${c.roi.toFixed(1)}%</strong></span>${arrow()}</a>`).join('')}</div></section>`}
function traderHome(){const member=!!state.membership;return `<div class="trader-home">${traderHero()}<div class="trader-demo-note">${icon('info')} Interactive design preview · Membership and activity are saved locally. No live competition or order execution is connected.</div>${member?traderMemberBoard():traderCommunityFinder()}${member?'':traderGettingStarted()}${homeBattleFeature()}${traderStandings()}${member?traderCommunityFinder():''}${traderLeaderStrip()}<section class="trader-world-secondary"><div class="trader-section-heading"><div><span class="page-eyebrow">EXPLORE YOUR COMMUNITY’S HOME</span><h2>A world beyond the leaderboard.</h2><p>Four revealed communities. Eight cities in the mist.</p></div><span class="trader-optional-tag">OPTIONAL EXPLORATION</span></div><div id="guild-world-mount">${guildWorld()}</div></section><div class="trader-founder-invite"><div><h2>Bring your community to XOX.</h2><p>Create a guild, invite your people and prepare to compete.</p></div><button class="secondary" data-action="create">Create a guild ${arrow()}</button></div>${footer()}</div>`}
seasonHome=traderHome;worldHome=traderHome;
discoveryPage=function(){return breadcrumb('Find your community')+`<div class="trader-discover"><h1 class="trader-discover-title">Find a guild. Trade with your people.</h1>${traderCommunityFinder(true)}</div>`};
function traderRoot(){return routePath?$('#workspace'):$('#season-home')}
function updateTraderSearch(){const mount=traderRoot()?.querySelector('#trader-guild-results');if(mount)mount.innerHTML=traderSearchCards();const count=traderRoot()?.querySelector('#trader-guild-count');if(count)count.textContent=traderFilteredGuilds().length+' guilds'}
function openGuildInvite(){open(`<div class="trader-invite-modal"><span class="page-eyebrow">YOUR COMMUNITY’S INVITATION</span><h2>Join through your people.</h2><p>Paste a guild invite link or guild ID to open its profile before joining.</p><form class="form" id="trader-invite-form"><label for="trader-invite-link">Guild invite link or ID</label><input id="trader-invite-link" name="invite" required maxlength="500" placeholder="…/#/guild/huddle or huddle" autofocus><p id="trader-invite-error" role="alert"></p><button class="primary" type="submit">Review guild ${arrow()}</button></form><small>This prototype recognises guilds available in this demo.</small></div>`)}
const traderBaseRoute=renderRoute;renderRoute=function(scroll=true){traderBaseRoute(scroll);if(!routePath)document.title='XOX Guilds — Join your community. Compete together.'};
document.addEventListener('input',e=>{if(e.target.id==='trader-guild-search'){traderUI.query=e.target.value;updateTraderSearch()}});
document.addEventListener('click',e=>{const find=e.target.closest('[data-find-community]');if(find){e.preventDefault();$('#find-community')?.scrollIntoView({behavior:'smooth',block:'start'});$('#trader-guild-search')?.focus({preventScroll:true})}const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-open-guild-invite'))openGuildInvite();if(b.hasAttribute('data-reset-guild-search')){traderUI.query='';const input=traderRoot()?.querySelector('#trader-guild-search');if(input)input.value='';updateTraderSearch()}});
document.addEventListener('submit',e=>{if(e.target.id!=='trader-invite-form')return;e.preventDefault();const raw=String(new FormData(e.target).get('invite')||'').trim();let id=raw;if(raw.includes('/')){try{const url=new URL(raw,location.href);const match=(url.hash||url.pathname).match(/(?:^#?\/?)guild\/([a-zA-Z0-9_-]+)(?:[/?#]|$)/);id=match?match[1]:''}catch{id=''}}const g=guildById(id);if(!g){$('#trader-invite-error').textContent='This invite does not match an available demo guild. Check the link or search by community name.';return}modal.close();navigate('guild/'+g.id)});
renderRoute(false);
